Both sets of errors are fixed in the two scenario files. `h.d.ts` and `kernel.d.ts` are unchanged, and what each scenario expresses is unchanged.

**Scenario 1 (lines 174 and 196).** The Linear and folder `read` callbacks return `origin: 'tracker'` and `origin: 'folder'`. Their contextual return type is `NoInfer<T>`. In this compile the literal was not kept: TypeScript widened `'tracker'` to `string`. That points to the compiler not seeing through `NoInfer` when it decides whether to keep a literal type.
- The Bug data schema is now a named value, `bugData`, with `type BugData = z.infer<typeof bugData>`.
- Both callbacks declare their return type as `BugData`.
- This is an annotation, not a cast, and the surface stays as it was.

**Scenario 6 (lines 61–67, and the `unknown` errors at line 108).** There was a circular inference:
- The model policies' callbacks pass `reviewerA` and `reviewerB` as arguments.
- Each seat's initializer passes its own policy to `.model(...)`.
- So working out the policy's type needed the seat's type, which needed the policy's type, and everything in the cycle fell to implicit `any`.

The fixes:
- `reviewerAModel` and `reviewerBModel` are now annotated as `ModelPolicy`, the public alias already exported from `harness-dsl`. That breaks the cycle.
- `actedOnRate` now declares a return type of `Rate`.
- With the seats typed, `first.value` and `second.value` infer correctly again, so the line 108 errors go away.

=== FILE: scenarios/01-coding-team.ts ===
import { z } from 'zod';
import { H } from 'harness-dsl';
import type { PendingView, SupplyOf } from 'harness-dsl';
import * as claudeCode from 'harness-dsl/claude-code';
import * as anthropic from 'harness-dsl/anthropic';
import * as linear from 'harness-dsl/linear';
import * as folder from 'harness-dsl/folder';
import * as sqlite from 'harness-dsl/sqlite';
import * as jsonl from 'harness-dsl/jsonl';
import * as git from 'harness-dsl/git';
import * as shell from 'harness-dsl/shell';
import * as markdown from 'harness-dsl/markdown';

const todo = H.state('todo', 'pending');
const decomposed = H.state('decomposed', 'waiting');
const done = H.state('done', 'terminal', 'success');
const stuck = H.state('stuck', 'terminal', 'failure');
const wontFix = H.state('wontFix', 'terminal', 'neutral');
const due = H.state('due', 'pending');
const up = H.state('up', 'terminal', 'success');
const down = H.state('down', 'terminal', 'failure');

const bugData = z.object({
  title: z.string(),
  description: z.string(),
  origin: z.enum(['tracker', 'folder', 'operator', 'heartbeat']),
});
type BugData = z.infer<typeof bugData>;

const Bug = H.kind('Bug')
  .data(bugData)
  .states(todo, done, stuck, wontFix);

const Feature = H.kind('Feature')
  .data(z.object({ title: z.string(), description: z.string(), epic: z.string().optional() }))
  .states(todo, done, stuck);

const Epic = H.kind('Epic')
  .data(z.object({ title: z.string(), description: z.string() }))
  .states(todo, decomposed, done, stuck);

const ServiceHeartbeat = H.kind('ServiceHeartbeat')
  .data(z.object({ service: z.string() }))
  .states(due, up, down);

const builderRole = H.role('builder')
  .input(z.object({
    title: z.string(),
    description: z.string(),
    feedback: z.array(z.string()),
    ownerAnswer: z.string().optional(),
  }))
  .output(z.object({ summary: z.string(), question: z.string().optional() }))
  .prompt(input => [
    `Build: ${input.title}`,
    input.description,
    input.feedback.length > 0 ? `Fix these deficits first:\n${input.feedback.join('\n')}` : '',
    input.ownerAnswer !== undefined ? `The owner answered: ${input.ownerAnswer}` : '',
    'If you need an owner decision, return it as question instead of guessing.',
  ].join('\n\n'))
  .intents(['read', 'edit', 'execute']);

const auditorRole = H.role('auditor')
  .input(z.object({ title: z.string(), description: z.string(), summary: z.string() }))
  .output(z.object({ deficits: z.array(z.string()) }))
  .prompt(input => `Audit the change for "${input.title}".\n\n${input.description}\n\nBuilder summary:\n${input.summary}\n\nList every deficit, or none.`)
  .intents(['read', 'execute']);

const plannerRole = H.role('planner')
  .input(z.object({ title: z.string(), description: z.string() }))
  .output(z.object({ features: z.array(z.object({ title: z.string(), description: z.string() })) }))
  .prompt(input => `Decompose the epic "${input.title}" into independently shippable features.\n\n${input.description}`)
  .intents(['read']);

const sonnet = anthropic.model('claude-sonnet-4-5');
const opus = anthropic.model('claude-opus-4-1');

const subscriptionA = claudeCode.subscription('claude-max-a', { token: H.env('CLAUDE_TOKEN_A') });
const subscriptionB = claudeCode.subscription('claude-max-b', { token: H.env('CLAUDE_TOKEN_B') });
const subscriptionC = claudeCode.subscription('claude-max-c', { token: H.env('CLAUDE_TOKEN_C') });
const apiAccount = anthropic.account('anthropic-api', { apiKey: H.env('ANTHROPIC_API_KEY') });

const soonestExpiring = H.policy.account('soonestExpiringFirst', choice => {
  const subscriptions = choice.accounts
    .filter(view => view.eligible && view.account.plan === 'subscription' && view.usedShare < view.share)
    .sort((a, b) => (a.windowEndsAt?.getTime() ?? Number.MAX_SAFE_INTEGER) - (b.windowEndsAt?.getTime() ?? Number.MAX_SAFE_INTEGER));
  const first = subscriptions[0];
  if (first) return first.account;
  const metered = choice.accounts.find(view => view.eligible && view.account.plan === 'metered');
  return metered ? metered.account : null;
});

const claudePool = H.pool('claude', [
  { account: subscriptionA, share: 0.5, serves: [sonnet, opus] },
  { account: subscriptionB, share: 0.3, serves: [sonnet, opus] },
  { account: subscriptionC, share: 0.2, serves: [sonnet, opus] },
  { account: apiAccount, share: 1, serves: [sonnet, opus] },
], soonestExpiring);

const builderModel = H.policy.model('cheaperUntilItSlips', [sonnet, opus], choice => {
  const cheaper = choice.metrics.successRate({ kind: choice.kind, seat: choice.seat, model: sonnet, days: 14 });
  if (cheaper.samples < 20) return sonnet;
  return cheaper.value !== null && cheaper.value < 0.85 ? opus : sonnet;
});

const experience = H.journal('experience', H.memory('experience', 'experience'), jsonl.memory('memory/experience.jsonl'));
const taste = H.journal('taste', H.memory('taste', 'taste'), jsonl.memory('memory/taste.jsonl'));

const worktrees = git.worktree('worktrees', { repo: '.', slots: 3 });
const local = shell.local('local', { slots: 4 });

const projectChecks = H.command('projectChecks')
  .argv(() => ['npm', 'run', 'check'])
  .on(worktrees)
  .recovery('rerun');

const builder = H.seat('builder', builderRole)
  .model(builderModel)
  .on(worktrees)
  .recalls(experience, taste)
  .guards(claudeCode.fileLeases(), claudeCode.stopCheck(projectChecks));

const auditor = H.seat('auditor', auditorRole)
  .model(opus)
  .on(worktrees)
  .recalls(experience)
  .records(experience);

const planner = H.seat('planner', plannerRole)
  .model(opus)
  .recalls(taste);

const ownerDecision = H.halt('ownerDecision', z.object({ answer: z.string() }));

const delivery = H.flow('delivery')
  .for(Bug, Feature)
  .params(z.object({ rounds: z.number().int().positive() }))
  .does(async ctx => {
    const { title, description } = ctx.unit.data;
    let feedback: string[] = [];
    let ownerAnswer: string | undefined;
    for (let round = 0; round < ctx.params.rounds; round += 1) {
      const built = await ctx.run(builder, { title, description, feedback, ownerAnswer });
      if (!built.ok) return ctx.fail(built.error);
      if (built.value.question !== undefined) {
        const decision = await ctx.halt(ownerDecision, built.value.question);
        ownerAnswer = decision.answer;
        continue;
      }
      const audit = await ctx.run(auditor, { title, description, summary: built.value.summary });
      if (!audit.ok) return ctx.fail(audit.error);
      if (audit.value.deficits.length === 0) return 'done';
      feedback = audit.value.deficits;
    }
    return ctx.fail('deficits remain after the last round');
  });

const healthCheck = H.command('healthCheck')
  .input(z.object({ service: z.string() }))
  .argv(input => ['curl', '-fsS', `https://${input.service}.internal/health`])
  .on(local)
  .recovery('rerun');

const heartbeat = H.flow('heartbeat')
  .for(ServiceHeartbeat)
  .does(async ctx => {
    const result = await ctx.run(healthCheck, { service: ctx.unit.data.service });
    return result.ok ? 'up' : 'down';
  });

const linearKey = H.env('LINEAR_API_KEY');

const bugTracker = linear.tracker(Bug, {
  apiKey: linearKey,
  team: 'PROD',
  label: 'bug',
  read: (issue): BugData => ({ title: issue.title, description: issue.description, origin: 'tracker' }),
  statuses: { todo: 'Todo', done: 'Done', stuck: 'Blocked', wontFix: 'Canceled' },
});

const featureTracker = linear.tracker(Feature, {
  apiKey: linearKey,
  team: 'PROD',
  label: 'feature',
  read: issue => ({ title: issue.title, description: issue.description, epic: issue.parentId }),
  statuses: { todo: 'Todo', done: 'Done', stuck: 'Blocked' },
});

const epicTracker = linear.tracker(Epic, {
  apiKey: linearKey,
  team: 'PROD',
  label: 'epic',
  read: issue => ({ title: issue.title, description: issue.description }),
  statuses: { todo: 'Todo', decomposed: 'In Progress', done: 'Done', stuck: 'Blocked' },
});

const bugFolder = folder.files(Bug, {
  dir: 'bugs',
  read: (file): BugData => ({ title: file.path, description: file.body, origin: 'folder' }),
});

const bugs = H.lane('bugs', Bug)
  .handler(delivery, { rounds: 3 })
  .attempts(2, { backoff: { first: { minutes: 10 } }, exhausted: 'stuck' })
  .suppliers(bugTracker, bugFolder, H.operator)
  .store(bugTracker)
  .wip(2);

const features = H.lane('features', Feature)
  .handler(delivery, { rounds: 5 })
  .attempts(2, { backoff: { first: { minutes: 10 } }, exhausted: 'stuck' })
  .suppliers(featureTracker, H.operator)
  .store(featureTracker);

const decomposition = H.flow('decomposition')
  .for(Epic)
  .does(async ctx => {
    const plan = await ctx.run(planner, { title: ctx.unit.data.title, description: ctx.unit.data.description });
    if (!plan.ok) return ctx.fail(plan.error);
    const children = await ctx.spawn(features, plan.value.features.map(feature => ({
      title: feature.title,
      description: feature.description,
      epic: ctx.unit.key,
    })));
    const finished = await ctx.suspend('decomposed', { children });
    return finished.every(child => child.state === 'done') ? 'done' : ctx.fail('a feature of the epic did not complete');
  });

const epics = H.lane('epics', Epic)
  .handler(decomposition)
  .attempts(1, { exhausted: 'stuck' })
  .suppliers(epicTracker)
  .store(epicTracker)
  .wip(1);

const services = ['api', 'web', 'payments'];

const heartbeats = H.lane('heartbeats', ServiceHeartbeat)
  .handler(heartbeat)
  .attempts(1, { exhausted: 'down' })
  .suppliers(H.schedule('heartbeatEveryFiveMinutes', ServiceHeartbeat, { every: { minutes: 5 } }, () =>
    services.map((service): SupplyOf<typeof ServiceHeartbeat> => ({ create: { service } }))));

const heartbeatFailureFilesBug = H.trigger(
  'heartbeatFailureFilesBug',
  H.on.enters(ServiceHeartbeat, 'down'),
  (event, act) => act.create(bugs, {
    title: `Heartbeat failed for ${event.unit.data.service}`,
    description: `The ${event.unit.data.service} health check failed at ${event.at.toISOString()}.`,
    origin: 'heartbeat',
  }),
);

const sixHoursMs = 6 * 60 * 60 * 1000;

const teamOrder = H.policy.scheduler('heartbeatsBugsFeaturesEpics', view => {
  const rank = (unit: PendingView): number => {
    if (unit.is(ServiceHeartbeat)) return 0;
    if (unit.is(Feature) && unit.waitedMs > sixHoursMs) return 0.5;
    if (unit.is(Bug)) return 1;
    if (unit.is(Feature)) return 2;
    return 3;
  };
  return { start: view.pending.slice().sort((a, b) => rank(a) - rank(b) || b.waitedMs - a.waitedMs) };
});

const productionProbe = H.command('productionProbe')
  .argv(() => ['curl', '-fsS', 'https://app.example.com/health'])
  .on(local)
  .recovery('rerun');

const supervisor = claudeCode.supervisor({
  grants: [
    H.ops.readWork,
    H.ops.writeWork,
    H.ops.resolveHalts,
    H.ops.writeMemory,
    H.ops.readTelemetry,
    H.ops.readAccounts,
    H.ops.setShares,
    H.operation('probeProduction', productionProbe),
  ],
});

export const codingTeam = H.harness('coding-team')
  .ledger(sqlite.ledger('.harness/ledger.sqlite'))
  .lanes(heartbeats, bugs, features, epics)
  .pools(claudePool)
  .triggers(heartbeatFailureFilesBug)
  .scheduler(teamOrder)
  .clients(supervisor)
  .observers(markdown.board('BOARD.md'), markdown.telemetry('TELEMETRY.md'));
=== END ===

=== FILE: scenarios/06-content-taste.ts ===
import { z } from 'zod';
import { H } from 'harness-dsl';
import type { Metrics, Model, ModelPolicy, Rate, SeatRef, SupplyOf } from 'harness-dsl';
import * as claudeCode from 'harness-dsl/claude-code';
import * as anthropic from 'harness-dsl/anthropic';
import * as sqlite from 'harness-dsl/sqlite';
import * as jsonl from 'harness-dsl/jsonl';
import * as shell from 'harness-dsl/shell';
import * as http from 'harness-dsl/http';
import * as markdown from 'harness-dsl/markdown';

const sections = z.enum(['news', 'sports', 'opinion', 'culture']);
const sectionFacet = H.facet('section', sections);

const submitted = H.state('submitted', 'pending');
const returned = H.state('returned', 'waiting');
const accepted = H.state('accepted', 'terminal', 'success');
const stuck = H.state('stuck', 'terminal', 'failure');

const Draft = H.kind('Draft')
  .data(z.object({
    title: z.string(),
    body: z.string(),
    section: sections,
    editorNotes: z.string().optional(),
  }))
  .states(submitted, returned, accepted, stuck);

const reviewerRole = H.role('reviewer')
  .input(z.object({ title: z.string(), body: z.string(), section: sections }))
  .output(z.object({ critique: z.string() }))
  .prompt(input => `Critique this ${input.section} draft as the editor would.\n\n# ${input.title}\n\n${input.body}`);

const opusA = anthropic.model('claude-opus-4-1');
const opusB = anthropic.model('claude-opus-4');
const sonnetA = anthropic.model('claude-sonnet-4-5');
const sonnetB = anthropic.model('claude-sonnet-4');

const apiAccount = anthropic.account('anthropic-api', { apiKey: H.env('ANTHROPIC_API_KEY') });
const pool = H.pool('anthropic', [{ account: apiAccount, share: 1, serves: [opusA, opusB, sonnetA, sonnetB] }]);

const taste = H.journal('editorTaste', H.memory('editorTaste', 'taste'), jsonl.memory('memory/taste.jsonl'));
const factLessons = H.journal('factLessons', H.memory('factLessons', 'experience'), jsonl.memory('memory/facts.jsonl'));

function actedOnRate(metrics: Metrics, seat: SeatRef): Rate {
  return metrics.rate({ among: editorial.resolved(), count: { ...editorial.resolved(), seat }, days: 90 });
}

function swapIfWeaker(metrics: Metrics, own: SeatRef, other: SeatRef, primary: Model, spare: Model): Model {
  const mine = metrics.rateBy({
    among: editorial.resolved(),
    count: { ...editorial.resolved(), seat: own },
    by: { modelOf: own },
    days: 90,
  }).of(primary);
  const theirs = actedOnRate(metrics, other);
  if (mine.samples < 50 || theirs.samples < 50) return primary;
  return (mine.value ?? 0) < (theirs.value ?? 0) ? spare : primary;
}

const reviewerAModel: ModelPolicy = H.policy.model('reviewerAModel', [opusA, opusB], choice =>
  swapIfWeaker(choice.metrics, reviewerA, reviewerB, opusA, opusB));
const reviewerBModel: ModelPolicy = H.policy.model('reviewerBModel', [sonnetA, sonnetB], choice =>
  swapIfWeaker(choice.metrics, reviewerB, reviewerA, sonnetA, sonnetB));

const reviewerA = H.seat('reviewerA', reviewerRole).model(reviewerAModel).recalls(taste, factLessons);
const reviewerB = H.seat('reviewerB', reviewerRole).model(reviewerBModel).recalls(taste, factLessons);

const editorial = H.halt('editorial', z.object({
  action: z.enum(['accept', 'return']),
  notes: z.string().optional(),
  actedOn: z.array(z.enum(['reviewerA', 'reviewerB'])),
})).credits(decision => decision.actedOn.map(reviewer => reviewer === 'reviewerA' ? reviewerA : reviewerB));

const local = shell.local('local', { slots: 2 });

const factCheck = H.command('factCheck')
  .input(z.object({ body: z.string() }))
  .output(z.object({ repeats: z.array(z.object({ mistake: z.string(), lesson: z.string() })) }))
  .argv(input => ['fact-check', '--text', input.body])
  .on(local)
  .recovery('rerun');

const mergeCritiques = H.command('mergeCritiques')
  .input(z.object({ first: z.string(), second: z.string() }))
  .argv(input => ['merge-critiques', '--a', input.first, '--b', input.second])
  .on(local)
  .recovery('rerun');

const review = H.flow('review')
  .for(Draft)
  .does(async ctx => {
    const { title, body, section } = ctx.unit.data;
    const facts = await ctx.run(factCheck, { body });
    if (facts.ok) {
      for (const repeat of facts.value.repeats) {
        await ctx.remember(factLessons, {
          text: `When reviewing a draft, verify ${repeat.mistake}`,
          because: repeat.lesson,
          when: { roles: [reviewerRole] },
        });
      }
    }
    const first = await ctx.run(reviewerA, { title, body, section });
    if (!first.ok) return ctx.fail(first.error);
    const second = await ctx.run(reviewerB, { title, body, section });
    if (!second.ok) return ctx.fail(second.error);
    const merged = await ctx.run(mergeCritiques, { first: first.value.critique, second: second.value.critique });
    if (!merged.ok) return ctx.fail(merged.error);
    const decision = await ctx.halt(editorial, merged.value);
    if (decision.action === 'accept') return 'accepted';
    await ctx.update({ editorNotes: decision.notes ?? '' });
    return 'returned';
  });

const cmsHeaders = { Authorization: H.env('CMS_TOKEN') };

const cmsPoll = http.poll(Draft, {
  url: 'https://cms.example.com/api/drafts?status=ready,revised',
  every: { minutes: 15 },
  headers: cmsHeaders,
  body: z.object({
    drafts: z.array(z.object({
      id: z.string(),
      title: z.string(),
      body: z.string(),
      section: sections,
      status: z.enum(['ready', 'revised']),
    })),
  }),
  read: body => body.drafts.map((draft): SupplyOf<typeof Draft> => draft.status === 'ready'
    ? { create: { title: draft.title, body: draft.body, section: draft.section }, key: draft.id }
    : { update: draft.id, patch: { title: draft.title, body: draft.body }, state: 'submitted' }),
});

const drafts = H.lane('drafts', Draft)
  .handler(review)
  .attempts(2, { backoff: { first: { minutes: 5 } }, exhausted: 'stuck' })
  .suppliers(cmsPoll)
  .store(http.store(Draft, { url: 'https://cms.example.com/api/drafts', headers: cmsHeaders, stateField: 'review_state' }))
  .facet(sectionFacet, data => data.section);

const notesBecomeTaste = H.trigger(
  'notesBecomeTaste',
  H.on.enters(Draft, 'returned'),
  (event, act) => act.remember(taste, {
    text: `When reviewing a ${event.unit.data.section} draft, check for what the editor asked: ${event.unit.data.editorNotes ?? ''}`,
    because: `the editor returned "${event.unit.data.title}" with these notes`,
    when: { roles: [reviewerRole], facets: [sectionFacet.of(event.unit.data.section)] },
    status: 'candidate',
  }),
);

const supervisor = claudeCode.supervisor({
  grants: [
    H.ops.readWork,
    H.ops.resolve(editorial),
    H.ops.readMemory,
    H.ops.writeMemory,
    H.ops.curateMemory,
    H.ops.readTelemetry,
  ],
});

export const contentReview = H.harness('content-review')
  .ledger(sqlite.ledger('.harness/ledger.sqlite'))
  .lanes(drafts)
  .pools(pool)
  .triggers(notesBecomeTaste)
  .clients(supervisor)
  .observers(markdown.board('BOARD.md'), markdown.telemetry('TELEMETRY.md'));
=== END ===

The only error is in the scenario. Its `as const satisfies { readonly maxAttempts: number }` checked the retry literal against a narrower inline type than the real `Retry` interface, so the `backoff` field failed TypeScript's excess-property check.

The fix annotates the constant with the DSL's own `Retry` type. That keeps it checked against the real shape and also removes the `as const`, which counted as an `as`. Nothing else changes, and the surface needs no edit.

=== FILE: scenarios/05-data-approval.ts ===
import { z } from 'zod';
import { H } from 'harness-dsl';
import type { Retry } from 'harness-dsl';
import { anthropic } from 'harness-dsl/anthropic';
import { claudeCode } from 'harness-dsl/claude-code';
import { sqlite } from 'harness-dsl/sqlite';
import { jsonl } from 'harness-dsl/jsonl';
import { ssh } from 'harness-dsl/ssh';
import { markdown } from 'harness-dsl/markdown';

const timeZone = 'Europe/Berlin';
const sourceSchema = z.enum(['crm', 'billing', 'inventory', 'web']);
const loadItem = z.object({ source: sourceSchema, night: z.string() });

const Scheduled = H.state('Scheduled', 'pending');
const Loaded = H.terminal('Loaded', 'success');
const LoadedWithWarnings = H.terminal('LoadedWithWarnings', 'success');
const Rejected = H.terminal('Rejected', 'neutral');
const Expired = H.terminal('Expired', 'neutral');
const Failed = H.terminal('Failed', 'failure');

const NightlyLoad = H.kind('NightlyLoad')
  .attributes(loadItem)
  .states(Scheduled, Loaded, LoadedWithWarnings, Rejected, Expired, Failed)
  .key(a => `${a.source}@${a.night}`)
  .initial(Scheduled);

const etlHost = ssh.host('etl-host', { host: 'etl.internal', user: 'etl', key: H.env('SSH_KEY_ETL') }).slots(2);

const extract = H.command('extract')
  .input(loadItem)
  .argv(i => ['./etl/extract.sh', i.source, i.night])
  .runner(etlHost);
const validate = H.command('validate')
  .input(loadItem)
  .argv(i => ['./etl/validate.sh', i.source, i.night])
  .runner(etlHost)
  .acceptExitCodes(0, 1);
const load = H.command('load')
  .input(loadItem)
  .argv(i => ['./etl/load.sh', i.source, i.night])
  .runner(etlHost);
const verify = H.command('verify')
  .input(loadItem)
  .argv(i => ['./etl/verify.sh', i.source, i.night])
  .runner(etlHost)
  .output(z.object({ driftPercent: z.number() }));

const threeRetriesWithBackoff: Retry = { maxAttempts: 4, backoff: 'exponential', initialDelayMs: 60000 };

const validationReview = H.halt('validation-review').decision(z.object({ proceed: z.boolean(), note: z.string().optional() }));
const loadApproval = H.halt('load-approval').decision(z.object({ approved: z.boolean(), note: z.string().optional() }));

const loadQuota = sqlite.quota('data-api', { path: './.harness/quota.sqlite' });
const dataAccount = anthropic.account('data-api', { apiKey: H.env('ANTHROPIC_API_KEY'), quota: loadQuota });
const summaryRole = H.role('anomaly-summarizer')
  .intents('read')
  .instructions('Summarize the anomalies in plain language for the approver. Emphasize what the approver has asked for.');
const summarizer = H.seat('anomaly-summarizer')
  .role(summaryRole)
  .model(anthropic.model('sonnet', { id: 'claude-sonnet-4-5' }))
  .pool(H.pool('data').accounts(dataAccount))
  .output(z.object({ summary: z.string() }));

const nightly = H.flow('nightly-load')
  .input(loadItem)
  .step('extract', extract, ctx => ctx.unit.attributes, { retry: threeRetriesWithBackoff, afterCrash: 'rerun' })
  .step('validate', validate, ctx => ctx.unit.attributes, { afterCrash: 'rerun' })
  .halt('validationReview', validationReview, {
    when: ctx => ctx.steps.validate.exitCode !== 0,
    ask: ctx => `Validation failed for ${ctx.unit.attributes.source} (${ctx.unit.attributes.night}):\n${ctx.steps.validate.stdout}`,
  })
  .exit('validationRejected', ctx => ctx.steps.validationReview?.proceed === false)
  .step('summarize', summarizer, ctx => ({
    task: `Summarize anomalies for the ${ctx.unit.attributes.source} load of ${ctx.unit.attributes.night}.\n\nValidation report:\n${ctx.steps.validate.stdout}`,
  }))
  .halt('approval', loadApproval, {
    ask: ctx => `Approve the ${ctx.unit.attributes.source} load of ${ctx.unit.attributes.night}?\n\n${ctx.steps.summarize.summary}`,
  })
  .exit('approvalRejected', ctx => !ctx.steps.approval.approved)
  .step('load', load, ctx => ctx.unit.attributes, { retry: threeRetriesWithBackoff, afterCrash: 'rerun' })
  .step('verify', verify, ctx => ctx.unit.attributes, { afterCrash: 'rerun' })
  .exit('loaded', ctx => ctx.steps.verify.driftPercent === 0)
  .exit('loadedWithWarnings');

const loadLane = H.lane('nightly-loads', NightlyLoad)
  .supply(H.clock('nightly-0200').at('02:00', { tz: timeZone }), (tick, to) =>
    sourceSchema.options.map(source => to.create({ source, night: tick.at.toISOString().slice(0, 10) })),
  )
  .handler(nightly, {
    exits: {
      validationRejected: Rejected,
      approvalRejected: Rejected,
      loaded: Loaded,
      loadedWithWarnings: LoadedWithWarnings,
    },
  })
  .store(sqlite.store({ path: './.harness/loads.sqlite' }))
  .retry({ maxAttempts: 1, exhausted: Failed })
  .on(H.cancel, { enter: Expired, at: ['approval'] });

const approvalDeadline = H.trigger('approval-deadline')
  .on(H.when.timer(loadLane, { at: u => H.nextTime('09:00', { after: u.createdAt, tz: timeZone }) }))
  .signal(H.cancel, loadLane, e => ({ key: e.unit.key, payload: { reason: 'approval not given by 09:00' } }));

const tasteJournal = H.journal('approver-taste', H.memory('approver-taste', 'taste'))
  .store(jsonl.memoryStore({ path: './memory/taste.jsonl' }))
  .recall({ by: 'specificity', limit: 10 })
  .readBy(summaryRole);

const approver = claudeCode.supervisor('approver', {
  grants: [
    H.ops.workRead,
    H.ops.resolve(validationReview, loadApproval),
    H.ops.attemptsRecover,
    H.ops.memoryRead,
    H.ops.memoryWrite,
    H.ops.telemetryRead,
  ],
  port: H.slot.port(0),
});

export const dataHarness = H.harness('nightly-data')
  .ledger(sqlite.ledger({ path: './.harness/ledger.sqlite' }))
  .lanes(loadLane)
  .journals(tasteJournal)
  .triggers(approvalDeadline)
  .scheduler(H.scheduler('nightly').standard(loadLane))
  .clients(approver)
  .observers(markdown.board({ path: './BOARD.md' }), markdown.telemetry({ path: './TELEMETRY.md' }));

void dataHarness.start();
